import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"dom-animation","description":"DOM 定位与动画开发规范。适用于涉及 DOM 定位、PopperJS、CSS 动画、transform 的开发场景。涵盖渲染链路分析、调试日志、生命周期管理等核心规则。","frontmatter":{"title":"dom-animation","description":"DOM 定位与动画开发规范。适用于涉及 DOM 定位、PopperJS、CSS 动画、transform 的开发场景。涵盖渲染链路分析、调试日志、生命周期管理等核心规则。"},"headers":[],"relativePath":"skills/dom-animation.md","filePath":"skills/dom-animation.md","lastUpdated":null}'),l={name:"skills/dom-animation.md"};function n(d,e,r,c,s,m){return t(),i("div",null,[...e[0]||(e[0]=[a('<blockquote><p>📄 本页由源文件 <code>skills/dom-animation/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="dom-animation" tabindex="-1">dom-animation <a class="header-anchor" href="#dom-animation" aria-label="Permalink to &quot;dom-animation&quot;">​</a></h1><blockquote><p>从开发规范附录 G 迁移，按需加载。适用于涉及 DOM 定位、PopperJS、CSS 动画、transform 的开发场景。</p></blockquote><h2 id="_1-必须完整分析渲染链路" tabindex="-1">1. 必须完整分析渲染链路 <a class="header-anchor" href="#_1-必须完整分析渲染链路" aria-label="Permalink to &quot;1. 必须完整分析渲染链路&quot;">​</a></h2><ul><li>✅ 从组件追溯到底层实现（如 Bubble → Popover → OverlayLayer → PopperJS → ScaleTransition）</li><li>✅ 明确 DOM 节点完整生命周期（插入 → 定位 → 动画 → 可见）</li><li>✅ 明确 transform/transition/animation 的具体参数和时序</li><li>❌ 禁止跳过源码分析直接基于表面行为假设</li></ul><h2 id="_2-第一版代码必须包含调试日志" tabindex="-1">2. 第一版代码必须包含调试日志 <a class="header-anchor" href="#_2-第一版代码必须包含调试日志" aria-label="Permalink to &quot;2. 第一版代码必须包含调试日志&quot;">​</a></h2><ul><li>✅ 关键 DOM API 返回值（<code>getBoundingClientRect</code>、<code>offsetWidth</code>、<code>getComputedStyle</code>）</li><li>✅ 计算过程中间值（overflowLeft、overflowRight、offset）</li><li>✅ 时序信息（哪个回调先触发、动画处于什么阶段）</li><li>❌ 禁止连续多轮修复都不加日志让用户&quot;肉眼验证&quot;</li></ul><h2 id="_3-offsetwidth-优先于-getboundingclientrect" tabindex="-1">3. offsetWidth 优先于 getBoundingClientRect <a class="header-anchor" href="#_3-offsetwidth-优先于-getboundingclientrect" aria-label="Permalink to &quot;3. offsetWidth 优先于 getBoundingClientRect&quot;">​</a></h2><p>当存在 CSS transform（如 <code>scale3d</code>）时：</p><ul><li><code>getBoundingClientRect()</code> → transform 后的视觉尺寸（随动画逐帧变化）</li><li><code>offsetWidth</code>/<code>offsetHeight</code> → CSS 布局真实尺寸（不受 transform 影响）</li><li>✅ 定位计算用 <code>offsetWidth</code>/<code>offsetHeight</code></li><li>❌ 禁止在 transform 动画时用 <code>getBoundingClientRect</code> 做定位计算</li></ul><h2 id="_4-首次锁定-模式" tabindex="-1">4. &quot;首次锁定&quot;模式 <a class="header-anchor" href="#_4-首次锁定-模式" aria-label="Permalink to &quot;4. &quot;首次锁定&quot;模式&quot;">​</a></h2><ul><li>✅ 计算一次 → 锁定 → 后续不再重算（如 <code>initialAdjustDoneRef</code>）</li><li>❌ 禁止动画进行中持续重算定位偏移</li></ul><h2 id="_5-dom-查询时序-优化时破坏-dom-获取时序反模式" tabindex="-1">5. DOM 查询时序（优化时破坏 DOM 获取时序反模式） <a class="header-anchor" href="#_5-dom-查询时序-优化时破坏-dom-获取时序反模式" aria-label="Permalink to &quot;5. DOM 查询时序（优化时破坏 DOM 获取时序反模式）&quot;">​</a></h2><ul><li>DOM 查询需要每次回调获取最新引用时，<strong>必须放在回调内部</strong></li><li>唯一例外是用于注册 <code>ResizeObserver</code> 的一次性调用（但仅用于注册，不用于计算）</li><li>优化前必须分析执行时序：effect 执行时 DOM 是否已挂载？回调是否需要最新引用？</li><li><strong>优化核心原则</strong>：不改变代码行为，只改善代码表达。改变执行时序或闭包捕获的不是优化，是破坏。</li></ul>',14)])])}const h=o(l,[["render",n]]);export{u as __pageData,h as default};
